/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* reverseEvenLengthGroups(ListNode* head) {
        if (!head || !head->next) return head;
        ListNode dummy(0);
        dummy.next = head;
        ListNode* A = &dummy;
        int group = 1;
        while (A->next) {
            ListNode* B = A->next;
            ListNode* C = B;
            int len = 1;
            for (int i = 1; i < group && C->next; i++) {
                C = C->next;
                len++;
            }
            ListNode* D = C->next;
            if (len % 2 == 0) {
                C->next = nullptr;
                ListNode* prev = nullptr;
                ListNode* curr = B;
                while (curr) {
                    ListNode* nxt = curr->next;
                    curr->next = prev;
                    prev = curr;
                    curr = nxt;
                }
                A->next = prev;
                B->next = D;
                A = B;
            } else {
                A = C;
            }
            group++;
        }
        return dummy.next;
    }
};
